    required this.topic,
    required this.catalogVerifiedAt,
    this.publisherDateText,
    this.licenseName,
    this.rightsEvidenceLocator,
    this.attributionRequirements,
    this.rightsStatus = MedicalRightsStatus.linkOnlyPending,
  });

  factory MedicalResourceFixture.fromApiJson(Map<String, dynamic> json) {
    final publisherId = json['publisher_id'] as String;
    final sourceType = json['source_type'] as String;
    final jurisdiction = json['jurisdiction'] as String;
    final availableLanguages = (json['available_languages'] as List<dynamic>)
        .cast<String>();
    final title = json['title'] as String;
    final topic = json['topic'] as String;
    final officialLocator = json['official_locator'] as String;
    final englishLocator = json['english_official_locator'] as String?;
    return MedicalResourceFixture(
      id: json['source_id'] as String,
      stableReference: json['source_id'] as String,
      title: title,
      titleEn: json['title_en'] as String?,
      catalogSummary: json['catalog_summary'] as String,
      searchKeywords: (json['search_keywords'] as List<dynamic>).cast<String>(),
      officialLocator: officialLocator,
      englishOfficialLocator: englishLocator == officialLocator
          ? null
          : englishLocator,
      documentType: _documentTypeFromWire(sourceType),
      organization: _organizationFromPublisher(publisherId),
      jurisdiction: switch (jurisdiction) {
        'CN' || 'China' => MedicalJurisdiction.china,
        'TW' || 'Taiwan' => MedicalJurisdiction.taiwan,
        'US' => MedicalJurisdiction.unitedStates,
        _ => MedicalJurisdiction.international,
      },
      language:
          availableLanguages.contains('zh-Hans') &&
              availableLanguages.contains('en')
          ? MedicalResourceLanguage.bilingualChineseEnglish
          : availableLanguages.contains('zh-Hans')
          ? MedicalResourceLanguage.chinese
          : MedicalResourceLanguage.english,
      topic: _topicFromText('$topic $title'),
      catalogVerifiedAt: DateTime.parse(json['catalog_verified_at'] as String),
      publisherDateText: json['publisher_date_text'] as String?,
      licenseName: json['license_name'] as String?,
      rightsEvidenceLocator: json['rights_evidence_locator'] as String?,
      attributionRequirements: json['attribution_requirements'] as String?,
      rightsStatus: json['rights_mode'] == 'stored_text'
          ? MedicalRightsStatus.storedTextApproved
          : MedicalRightsStatus.linkOnlyPending,
    );
