MedicalDocumentType _documentTypeFromWire(String value) => switch (value) {
  'health_topic_summary' => MedicalDocumentType.healthTopicSummary,
  'medical_test_explanation' => MedicalDocumentType.medicalTestExplanation,
  'patient_education' => MedicalDocumentType.patientEducation,
  'preventive_health' => MedicalDocumentType.preventiveHealth,
  'clinical_guideline' => MedicalDocumentType.clinicalGuideline,
  'clinical_protocol' => MedicalDocumentType.clinicalProtocol,
  'practice_guideline' => MedicalDocumentType.practiceGuideline,
  'guidance' => MedicalDocumentType.guidance,
  _ => MedicalDocumentType.factSheet,
};

MedicalOrganization _organizationFromPublisher(String value) => switch (value) {
  'KBP-NHC' => MedicalOrganization.nationalHealthCommission,
  'KBP-TW-HPA' => MedicalOrganization.healthPromotionAdministration,
  'KBP-MEDLINEPLUS' => MedicalOrganization.medlinePlus,
  'KBP-NCI' => MedicalOrganization.nationalCancerInstitute,
  'KBP-NIMH' => MedicalOrganization.nationalInstituteOfMentalHealth,
  'KBP-ODPHP' =>
    MedicalOrganization.officeOfDiseasePreventionAndHealthPromotion,
  _ => MedicalOrganization.worldHealthOrganization,
};

MedicalResourceTopic _topicFromText(String value) {
  final text = value.toLowerCase();
  if (_containsAny(text, <String>[
    'mental',
    'depression',
    'anxiety',
    'psychosis',
    'schizophrenia',
    '心理',
    '精神',
  ])) {
    return MedicalResourceTopic.mentalHealth;
  }
  if (_containsAny(text, <String>[
    'pregnan',
    'prenatal',
    "child",
    'maternal',
    '妇幼',
    '孕',
    '儿童',
  ])) {
    return MedicalResourceTopic.maternalChildHealth;
  }
  if (_containsAny(text, <String>[
    'nutrition',
    'exercise',
    'fitness',
    'obesity',
    'sleep',
    'healthy aging',
    '营养',
    '运动',
    '肥胖',
  ])) {
    return MedicalResourceTopic.nutritionLifestyle;
  }
  if (_containsAny(text, <String>[
    'flu',
    'pneumonia',
    'tuberculosis',
    'hepatitis',
    'hiv',
    'infect',
    '传染',
    '感染',
  ])) {
    return MedicalResourceTopic.infectiousDisease;
  }
  if (_containsAny(text, <String>['injury', 'emergency', '急诊', '急救', '创伤'])) {
    return MedicalResourceTopic.injuryEmergency;
  }
  if (_containsAny(text, <String>['environment', 'climate', '环境', '气候'])) {
    return MedicalResourceTopic.environmentalHealth;
  }
  if (_containsAny(text, <String>[
    'health system',
    'workforce',
    'policy',
    '卫生系统',
    '政策',
  ])) {
    return MedicalResourceTopic.healthSystems;
  }
  return MedicalResourceTopic.chronicDisease;
}

bool _containsAny(String value, List<String> terms) =>
    terms.any(value.contains);

